'use strict';

/**
 * Least-recently-used cache backed by a Map.
 *
 * A Map iterates in insertion order, so we keep the least recently used entry
 * first and the most recently used entry last: refreshing an entry is a
 * delete + re-insert, and eviction removes the first key. All operations are
 * O(1) and keys follow Map (SameValueZero) semantics.
 */
class LRUCache {
  #map = new Map();

  constructor(capacity) {
    if (typeof capacity !== 'number' || !Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError(`LRUCache capacity must be a positive integer, got ${String(capacity)}`);
    }
    this.capacity = capacity;
  }

  get(key) {
    const map = this.#map;
    // Check has() rather than the value so stored `undefined` values still refresh.
    if (!map.has(key)) return undefined;
    const value = map.get(key);
    map.delete(key);
    map.set(key, value);
    return value;
  }

  set(key, value) {
    const map = this.#map;
    if (map.has(key)) {
      // Update in place: move to most recent without touching other entries.
      map.delete(key);
    } else if (map.size >= this.capacity) {
      map.delete(map.keys().next().value);
    }
    map.set(key, value);
    return this;
  }

  has(key) {
    return this.#map.has(key);
  }

  delete(key) {
    return this.#map.delete(key);
  }

  get size() {
    return this.#map.size;
  }
}

module.exports = { LRUCache };

